SELECT d.id, d.project_id, d.library_type, d.source_task_id, d.filename, d.content_type,
       d.size_bytes, d.content_hash, d.storage_path, d.created_at
FROM file_library_document d
JOIN project p ON p.id = d.project_id
WHERE d.id = #{id}
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
  AND p.deleted = 0

SELECT 
FROM file_library_document
WHERE project_id = #{projectId}
  AND content_hash = #{contentHash}

SELECT 
FROM file_library_document
WHERE project_id = #{projectId}
  AND library_type = #{libraryType}
  AND content_hash = #{contentHash}

SELECT 
FROM file_library_document
WHERE project_id = #{projectId}
  AND library_type = #{libraryType}
ORDER BY created_at DESC, id DESC
